WITH flattened AS (SELECT id, plan, effective_from, EXPLODE_OUTER(tier_limits) AS tier_value FROM price_tiers), matched_keys AS (SELECT plan, id FROM flattened INTERSECT ALL SELECT plan, id FROM price_tiers WHERE plan IN ('starter', 'basic', 'enterprise')), kept_rows AS (SELECT s.* FROM flattened s INNER JOIN matched_keys k ON s.plan = k.plan AND s.id = k.id), enriched AS (SELECT id, plan, effective_from, tier_value, PERCENT_RANK() OVER (PARTITION BY plan ORDER BY tier_value NULLS FIRST) AS tier_value_percent_rank, SUM(tier_value) OVER w_part AS plan_sum_tier_value, SUM(tier_value) OVER w_part AS plan_sum_tier_value_2 FROM kept_rows WINDOW w_part AS (PARTITION BY plan)), cleaned AS (SELECT id, plan, tier_value, tier_value_percent_rank, plan_sum_tier_value, plan_sum_tier_value_2, UPPER(plan) AS plan_upper, tier_value_percent_rank / NULLIF(tier_value, 0) AS tier_value_percent_rank_per_tier_value FROM enriched WHERE effective_from > TO_DATE('2024-10-18') AND plan_sum_tier_value <= 335) SELECT id, plan_sum_tier_value, plan_upper FROM cleaned ORDER BY id, plan_sum_tier_value;
